// Controller — container resolves constructor parameters
[ApiController]
[Route("api/orders")]
public sealed class OrdersController(IOrderService orders) : ControllerBase
{
    [HttpGet("{id}")]
    public async Task<ActionResult<OrderDto>> Get(Guid id)
        => Ok(await orders.GetByIdAsync(id));
}

public interface IOrderService
{
    Task<OrderDto?> GetByIdAsync(Guid id, CancellationToken ct = default);
}

public sealed class OrderService(AppDbContext db, ILogger<OrderService> logger)
    : IOrderService
{
    public async Task<OrderDto?> GetByIdAsync(Guid id, CancellationToken ct)
    {
        logger.LogInformation("Fetching order {OrderId}", id);
        return await db.Orders
            .Where(o => o.Id == id)
            .Select(o => new OrderDto(o.Id, o.Total))
            .FirstOrDefaultAsync(ct);
    }
}

// Prefer constructor injection — use manual resolution sparingly
public sealed class StartupMigrationRunner(IServiceProvider root)
{
    public async Task RunAsync()
    {
        using var scope = root.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        await db.Database.MigrateAsync();
    }
}

